// Input Validator — sanitize and validate incoming chat message
const message = $input.first().json?.chatInput?.trim() || '';

if (!message || message.length < 3) {
  throw new Error('Input too short or empty. Please provide a valid LinkedIn search request.');
}

if (message.length > 2000) {
  throw new Error('Input too long. Please keep your request under 2000 characters.');
}

// Pass through with sanitized input
return [{
  json: {
    ...$input.first().json,
    chatInput: message,
    validatedAt: new Date().toISOString()
  }
}];
